import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import { useDispatch, useSelector } from 'react-redux';
import { selectAuthToken, selectAuthTokenParsed } from '../../redux/features/Auth/AuthSelectors';
import { updateNamespaceRetention } from '../../redux/features/Namespace/NamespaceThunks';

const ShowRetentionDetails = ({ namespaces }) => {
  const navigate = useNavigate();
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [namespace] = useState(namespaces.namespaceName || '');
  const [retentionDays, setRetentionDays] = useState(namespaces.retentionPeriod || '');
  const [statusMessage, setStatusMessage] = useState('');

  const dispatch = useDispatch();
  const token = useSelector(selectAuthToken);
  const tokenParsed = useSelector(selectAuthTokenParsed);
  const userEmail = tokenParsed?.preferred_username || '';

  const handleUpdateRetention = async () => {
    setIsSubmitting(true);

    if (!retentionDays || retentionDays < 1) {
      setStatusMessage('Retention must be at least 1 day.');
      setIsSubmitting(false);
      return;
    }

    try {
      const result = await dispatch(
        updateNamespaceRetention({
          token,
          namespace,
          retention_days: parseInt(retentionDays, 10),
          email: userEmail,
        })
      ).unwrap();

      const newRetention = result?.newRetentionPeriod || result?.data?.newRetentionPeriod || result?.newRetentionPeriod;
      toast.success(result?.message || 'Retention updated!');
      if (newRetention) setRetentionDays(newRetention);
      setStatusMessage('');
    } catch (error) {
      toast.error(error?.message || 'Failed to update retention.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="w-full h-auto p-4 md:p-6">
      <div className="flex justify-center flex-1">
        <div className="w-full max-w-xl bg-white rounded-lg shadow-md p-4 md:p-6 flex flex-col justify-between border border-gray-100">
          <h2 className="text-lg font-semibold text-[#1a365d] mb-6">
            Namespace Details
          </h2>

          <div className="flex flex-col gap-6 w-full">
            <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-9">
              <label className="text-[0.9rem] text-gray-700 font-medium md:w-32">Namespace</label>
              <input
                type="text"
                value={namespace}
                readOnly
                className="flex-1 px-3 py-2 border border-gray-200 rounded shadow-sm bg-gray-50 cursor-not-allowed text-gray-500 text-sm"
              />
            </div>

            <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-9">
              <label className="text-[0.9rem] text-gray-700 font-medium md:w-32">Retention Period</label>
              <div className="flex-1 relative">
                <input
                  type="number"
                  value={retentionDays}
                  min={1}
                  onChange={(e) => {
                    const value = e.target.value;
                    if (value === '') {
                      setRetentionDays('');
                      return;
                    }
                    const parsed = parseInt(value);
                    if (!isNaN(parsed) && parsed >= 1) {
                      setRetentionDays(parsed);
                    }
                  }}
                  className="w-full px-3 py-2 border border-gray-300 rounded shadow-sm focus:outline-none focus:ring-2 focus:ring-[#1a365d]/50 focus:border-[#1a365d] text-sm"
                  placeholder="e.g. 7"
                  required
                />
                <span className="absolute right-3 top-2 text-xs text-gray-400">days</span>
              </div>
            </div>
          </div>

          <div className="flex justify-end mt-8">
            <button
              onClick={handleUpdateRetention}
              disabled={isSubmitting}
              className={`px-6 py-2 rounded text-white font-medium transition shadow-sm ${
                isSubmitting
                  ? 'bg-gray-400 cursor-not-allowed'
                  : 'bg-[#1a365d]/80 hover:bg-[#1a365d]'
              }`}
            >
              {isSubmitting ? 'Submitting...' : 'Submit'}
            </button>
          </div>

          {statusMessage && (
            <p className="text-sm text-center text-orange-600 mt-4">{statusMessage}</p>
          )}
        </div>
      </div>
    </div>
  );
};

export default ShowRetentionDetails;
